SELECT year(l.origination_date), COUNT(*), ROUND(100.0*COUNT(e.loan_id)/COUNT(*),2) FROM loan l LEFT JOIN (SELECT loan_id FROM loan_monthly_snapshot GROUP BY 1 HAVING MAX(days_past_due)>=90) e ON e.loan_id=l.loan_id WHERE l.lvr_at_origination_pct>90 AND l.lvr_at_origination_pct<=200 AND year(l.origination_date) BETWEEN 2019 AND 2024 GROUP BY 1 ORDER BY 1
